 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    by_color = {}
    for r, row in enumerate(grid):
        for c, color in enumerate(row):
            if color:
                by_color.setdefault(color, []).append((r, c))
    objects = []
    for color, cells in by_color.items():
        min_r = min(r for r, c in cells)
        max_r = max(r for r, c in cells)
        min_c = min(c for r, c in cells)
        max_c = max(c for r, c in cells)
        shape = [(r - min_r, c - min_c) for r, c in cells]
        objects.append((min_c, color, shape, max_r - min_r, max_c - min_c))
    objects.sort(key=lambda obj: obj[0])
    out = [[0] * w for _ in range(h)]
    anchor_r = anchor_c = 0
    for i, (_, color, shape, height_delta, width_delta) in enumerate(objects):
        for dr, dc in shape:
            r, c = anchor_r + dr, anchor_c + dc
            if 0 <= r < h and 0 <= c < w:
                out[r][c] = color
        anchor_r += height_delta
        anchor_c += width_delta
    return out
